    }

    @Test
    void corporatePlanDiscountsOfTheOtherCompanies() {
        assertEquals(new BigDecimal("143.96"), service.create(corporateStay("AGROVALE")).price().discount());
        assertEquals(new BigDecimal("194.95"), service.create(corporateStay("FARMAVIDA")).price().discount());
    }

    @Test
    void corporatePlanNeedsAKnownCompanyCode() {
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(corporateStay(null))));
