        assertEquals(new BigDecimal("820.00"), reservation.price().subtotal());
        assertEquals(new BigDecimal("0.00"), reservation.price().discount());
        assertEquals(new BigDecimal("820.00"), reservation.price().total());
        service.confirm(reservation.id());
        assertEquals(new BigDecimal("410.00"), service.cancel(reservation.id()).refund());
    }

    @Test
    void weekendPackageHasTheSamePriceInHighSeason() {
        assertEquals(new BigDecimal("520.00"),
                service.create(stay(101, "2027-07-09", "2027-07-11", 2, RatePlan.WEEKEND_PACKAGE)).price().total());
        assertEquals(new BigDecimal("1200.00"),
                service.create(stay(301, "2027-07-09", "2027-07-11", 2, RatePlan.WEEKEND_PACKAGE)).price().total());
    }

    @Test
    void weekendPackageOnlyFromFridayToSunday() {
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(stay(201, "2027-03-11", "2027-03-13", 2, RatePlan.WEEKEND_PACKAGE))));
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(stay(201, "2027-03-12", "2027-03-15", 2, RatePlan.WEEKEND_PACKAGE))));
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(stay(201, "2027-03-12", "2027-03-13", 2, RatePlan.WEEKEND_PACKAGE))));
    }

    @Test
    void longStayTakes10PercentOffAndRefundsEverything() {
        Reservation reservation = service.create(stay(101, "2027-03-01", "2027-03-08", 2, RatePlan.LONG_STAY));

